class SearchRequest(BaseModel):
    model_config = ConfigDict(
        extra="allow",
    )
    q: Annotated[str, Field(max_length=2048, min_length=1)]
    country: str | None = "us"
    """
    Country code (ISO 3166-1 alpha-2, case-insensitive; uk is accepted as gb). When omitted and location ends in a country name, that country is used. Russia (ru) is supported across all search verticals, including patents, using the shared proxy routes
    """
    language: str | None = "en"
    """
    Interface language: a language code with an optional region (e.g. en, ru, de, pt-br, zh-tw, es-419). Russian (ru) is supported across all search verticals; language does not change the selected country. On patents, a non-English code restricts publication language (ar, zh, da, nl, fi, fr, de, it, ja, ko, no, pt, ru, es, sv)
    """
    location: str | None = None
    """
    Free-text location, e.g. "Austin, Texas, United States"
    """
    uule: str | None = None
    """
    Pre-encoded Google location (overrides ll and location; percent-encoded values are decoded)
    """
    ll: str | None = None
    """
    Map point "@lat,lng,14z" (maps and places only; zoom optional, default 14z): the map is searched around that point at that zoom, wherever the request comes from. Overrides location
    """
    num: Annotated[int | None, Field(ge=1, le=100)] = 10
    """
    1–100. Up to 10 returns one page (10 results, 1 credit; trim it yourself for fewer). Above 10 on search and news is the depth bundle (7 credits for 100; values between round up to whole pages). On images a page is a block of up to 100 images (1 credit) and num (default 100) is how many of them to return; `page` moves to the next block. Other verticals return one page of 10
    """
    page: Annotated[int | None, Field(ge=1, le=10)] = 1
    time: str | None = None
    """
    Only results from the last hour/day/… (search, news, images, videos, shopping). A fallback engine without that window is skipped, never answered unfiltered
    """
    tbs: str | None = None
    """
    Advanced: raw Google tbs filter (e.g. qdr:d, qdr:w2, cdr:1,cd_min:1/1/2026,cd_max:1/31/2026); overrides time
    """
    device: str | None = "desktop"
    safe: str | None = "off"
    autocorrect: bool | None = True
    format: str | None = "json"
    fields: str | None = None
    """
    Comma-separated projection, e.g. "results.title,results.link,knowledge_graph"
    """
    include_content: Annotated[int | None, Field(ge=0, le=5)] = 0
    """
    Also fetch the top N organic pages as Markdown (+1 credit each fetched page)
    """
    ads: bool | None = False
    """
    Include sponsored results
    """
    max_age: Annotated[int | None, Field(ge=0)] = None
    """
    Accept a cached result up to this many seconds old (50% of credits on a hit)
    """
    engine: str | EngineParam1 | None = None
    """
    Which search providers may answer. `google` (the default) is Google only; within Google, SerpKite always fails over across its own proxy pools. `auto` allows falling back to other enabled providers, in route order, when Google is blocked or times out. A single other provider (`brave`) or a list (`["google","brave"]`, or `google,brave` in a query string) restricts the request to those providers. `meta.engine` always names the provider that answered and credits follow that provider's price. A key with "Allow fallback to other search engines" on treats a request without `engine` as `auto`. `consensus` (`/v1/search` only; 400 elsewhere, and it can't be combined with other names) queries several independent search indexes in parallel (at most one Bing-backed provider, so Yahoo or DuckDuckGo never count as agreeing with Bing), merges the results by URL and ranks them by how many providers returned each one. Each result lists its `sources`; `meta.engine` is `consensus` and `meta.route` lists every provider attempt. Up to three providers answer: a provider that fails or comes back empty hands its turn to the next one in the route. It stops once `num` unique results are in hand or after a few seconds, and costs the sum of one page at each provider that returned results (providers that failed, came back empty or were never started are free). `yandex` serves `/v1/search` from Yandex web search (no `time` filter or `safe: active`: a request naming it gets a 400 with them) and `/v1/maps`, `/v1/places` and `/v1/place` from Yandex Maps, where the deployment enables it (otherwise a 503 `unavailable`, not charged); with `auto` it is the last fallback there.
    """
    include_domains: str | DomainList1 | None = None
    """
    Only results from these domains (search, news, images, videos). Compiled into site: operators and enforced on the results. With engine=consensus, every provider gets the operators and only providers with a remaining result are billed
    """
    exclude_domains: str | DomainList1 | None = None
    """
    Drop results from these domains (search, news, images, videos)
    """
    boost_domains: str | DomainList1 | None = None
    """
    Move results from these domains to the top, keeping the order within both groups (search, news)
    """
    start_date: date_aliased | None = None
    """
    Only results published on or after this date, YYYY-MM-DD (search, news, images, videos). Can't be combined with time or tbs. A fallback engine without date ranges is skipped
    """
    end_date: date_aliased | None = None
    """
    Only results published on or before this date, YYYY-MM-DD. Can't be combined with time or tbs
    """
    highlights: bool | None = False
    """
    Return up to 3 query-ranked passages (`highlights`) of each page read by include_content instead of the whole page (search only; needs include_content; no extra credits)
    """
    include_answer: bool | None = False
    """
    Add a cited AI `answer` written by Claude over this response's results (search and news; +2 credits, +4 when it read pages via `include_content`; refunded with a `meta.warnings` entry when the model fails)
    """


